create extension if not exists pgcrypto;
create table if not exists public.games (id uuid primary key default gen_random_uuid(),provider text not null default 'manual',provider_game_id text,title text not null,slug text not null unique,description text not null default '',seo_description text,instructions text,controls text,embed_url text,thumbnail_url text,screenshots jsonb not null default '[]'::jsonb,category text not null default 'Casual',categories jsonb not null default '[]'::jsonb,tags jsonb not null default '[]'::jsonb,mobile_supported boolean not null default true,desktop_supported boolean not null default true,width integer,height integer,orientation text,language text default 'en',status text not null default 'pending' check (status in ('draft','pending','published','disabled')),featured boolean not null default false,trending boolean not null default false,badge text,emoji text default '🎮',gradient text default 'g1',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,provider_game_id));
create index if not exists games_status_idx on public.games(status); create index if not exists games_category_idx on public.games(category); create index if not exists games_provider_idx on public.games(provider); create index if not exists games_published_at_idx on public.games(published_at desc); create index if not exists games_featured_idx on public.games(featured,trending);
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text,seo_title text,enabled boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.game_events(id bigint generated by default as identity primary key,event_name text not null,game_slug text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists game_events_event_idx on public.game_events(event_name,created_at desc); create index if not exists game_events_game_idx on public.game_events(game_slug,created_at desc);
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),game_slug text not null,reason text not null,message text not null default '',email text not null default '',status text not null default 'open',created_at timestamptz not null default now()); create index if not exists reports_status_idx on public.reports(status,created_at desc);
create table if not exists public.redirects(id uuid primary key default gen_random_uuid(),old_path text not null unique,new_path text not null,status_code integer not null default 301,created_at timestamptz not null default now());
alter table public.games enable row level security; alter table public.categories enable row level security; alter table public.game_events enable row level security; alter table public.reports enable row level security; alter table public.redirects enable row level security;
drop policy if exists "published games are public" on public.games; create policy "published games are public" on public.games for select using(status='published'); drop policy if exists "enabled categories are public" on public.categories; create policy "enabled categories are public" on public.categories for select using(enabled=true);
insert into public.categories(name,slug,description,sort_order) values ('Action','action','Play free action games instantly in your browser.',0),('Adventure','adventure','Play free adventure games instantly in your browser.',1),('Arcade','arcade','Play free arcade games instantly in your browser.',2),('Board','board','Play free board games instantly in your browser.',3),('Casual','casual','Play free casual games instantly in your browser.',4),('Girls','girls','Play free styling and casual games instantly in your browser.',5),('Multiplayer','multiplayer','Play multiplayer browser games.',6),('Puzzle','puzzle','Play free puzzle games instantly in your browser.',7),('Racing','racing','Play free racing games instantly in your browser.',8),('Shooting','shooting','Play free shooting games instantly in your browser.',9),('Sports','sports','Play free sports games instantly in your browser.',10),('2 Player','2-player','Play free two-player games.',11) on conflict(slug) do nothing;